/**
 * 🔮 消費MP自動判定エンジン
 * ・新式大技(pow>=35 または 末尾10) ➔ 5P
 * ・新式初級(pow 1〜15) ➔ 2P
 * ・旧式上級(mete, ulti, holy, come) ➔ 5P
 * ・それ以外は全部 ➔ 3P
 */
window.getSpellCost = function(key) {
    // 1. 旧式の上級呪文だけ名指しで 5P
    if (['mete', 'ulti', 'holy', 'come'].includes(key)) {
        return 5;
    }

    // 2. 新式（NEW_SPELLS）に定義があれば pow から判定
    if (window.NEW_SPELLS && window.NEW_SPELLS[key]) {
        const pow = window.NEW_SPELLS[key].pow || 0;
        if (pow >= 35 || String(key).endsWith('10')) return 5;
        if (pow > 0 && pow <= 15) return 2;
    }

    // 3. それ以外（旧式の通常魔法・補助など）は全部 3P
    return 3;
};

// ⚡ 実際に使用された呪文の『呪文名』だけをログから抽出して onCast を発火させる
(function() {
    window.addEventListener("DOMContentLoaded", () => {
        if (typeof window.executeEnemySpecial === "function") {
            const originalSpecial = window.executeEnemySpecial;
            window.executeEnemySpecial = function(data, dmg, logTxt, effScr, isSpecial) {
                const res = originalSpecial.apply(this, arguments);
                const currentLog = res?.logTxt || "";

                // ログの最初の『〇〇』から実際に使われた呪文名を取得
                const match = currentLog.match(/『(.*?)』/);
                const castSpellName = match ? match[1] : null;

                if (castSpellName && window.NEW_SPELLS) {
                    const usedSpell = Object.values(window.NEW_SPELLS).find(s => s.name === castSpellName);
                    if (usedSpell && typeof usedSpell.onCast === "function") {
                        const extraTxt = usedSpell.onCast(data || { name: "敵" });
                        if (extraTxt) {
                            res.logTxt += extraTxt;
                        }
                    }
                }
                return res;
            };
        }
    });
})();


